func (srv *Server) readUDP(conn *net.UDPConn, timeout time.Duration) ([]byte, net.Addr, error) {
	conn.SetReadDeadline(time.Now().Add(timeout))
	var m []byte
	if srv.Pool {
		m = <-srv.get
	} else {
		m = make([]byte, srv.UDPSize)
	}
	n, a, e := conn.ReadFromUDP(m)
	if e != nil || n == 0 {
		if e != nil {
			return nil, nil, e
		}
		return nil, nil, ErrShortRead
	}
	m = m[:n]
	return m, a, nil
}
